@startuml
enum PriorityScore {
  High
  Low
}

enum TreatmentStage {
  Stage1
  Stage2
  Stage3
}

class Patient {
  + Name : string
  + ID : string
}

class Doctor {
  + Name : string
  + PractitionerNumber : int
}

class HeadDoctor {
  + Name : string
}

class Diagnosis {
  + Description : string
  + Date : date
}

class Treatment {
  + Name : string
  + Description : string
  + CurrentStage : TreatmentStage
}

class ConsentForm {
  + Signature : string
  + DateSigned : datetime
  + IsRetracted : boolean
}

class Illness {
  + Name : string
  + Priority : PriorityScore
}

class HospitalHouseMD {
  + Name : string
  + Address : string
}

Doctor "1..*" -- "0..*" Patient : treats
Doctor "1" -- "0..*" Diagnosis : makes
HeadDoctor "1" -- "0..*" Diagnosis : approves
Diagnosis "*" -- "1" Illness : identifies
Illness "1" -- "0..*" Treatment : appliesTo
Patient "1" -- "0..*" Treatment : receives
Patient "1" -- "0..*" ConsentForm : signs
ConsentForm "1" -- "0..*" Treatment : permitsUpgrade
HospitalHouseMD "1" -- "0..*" Treatment : database
@enduml

